def step(context):
    observations = context['inputs']['observations']
    if not observations:
        return {'outputs': {'decisions': [{'payload': {'empty_cycle': True}}], 'next': [{'payload': {'year': context['period']}}], 'world': []}, 'state': {'cycles': context['state'].get('cycles', 0) + 1}}

    world = observations[0]['payload']
    decisions = []
    total_reviews_generated = 0
    accepted_score_sum = 0.0
    accepted_count = 0

    for conference in world.get('conferences', {}).get('conferences', []):
        conference_id = conference['conference_id']
        papers = conference.get('submitted_papers', [])
        reviews_map = conference.get('reviews', {})

        # Calculate score for each paper based on reviews
        paper_scores = []
        for paper in papers:
            paper_id = paper['id']
            reviews = reviews_map.get(paper_id, [])
            if reviews:
                avg_score = sum(r.get('overall_score', 0.0) for r in reviews) / len(reviews)
            else:
                avg_score = 0.0
            paper_scores.append((paper_id, conference_id, avg_score, len(reviews)))

        # Sort papers by score descending to apply strict threshold
        paper_scores.sort(key=lambda x: x[2], reverse=True)

        # Apply a high threshold to select only the best papers
        # This increases the mean score of accepted papers and reduces the number of reviewed/accepted papers
        for paper_id, conf_id, score, num_reviews in paper_scores:
            if score >= 0.8:  # High threshold for acceptance
                decisions.append({
                    'payload': {
                        'paper_id': paper_id,
                        'conference_id': conf_id,
                        'decision': 'accept',
                        'final_score': score
                    }
                })
                accepted_score_sum += score
                accepted_count += 1
                # Assuming each accepted paper generates reviews proportional to its quality or a fixed cost
                # To minimize review_records, we assume fewer papers are reviewed/accepted
                total_reviews_generated += num_reviews 
            else:
                decisions.append({
                    'payload': {
                        'paper_id': paper_id,
                        'conference_id': conf_id,
                        'decision': 'reject',
                        'final_score': score
                    }
                })

    # If no papers were accepted, return an empty cycle to avoid zero division or stagnation
    if not decisions:
        decisions = [{'payload': {'empty_cycle': True}}]
        total_reviews_generated = 0
        accepted_score_sum = 0.0
        accepted_count = 0

    # Calculate average score of accepted papers for logging/feedback if needed
    avg_accepted_score = accepted_score_sum / accepted_count if accepted_count > 0 else 0.0

    return {
        'outputs': {
            'decisions': decisions,
            'next': [{'payload': {'year': context['period']}}],
            'world': [{'payload': world}] 
        },
        'state': {'cycles': context['state'].get('cycles', 0) + 1, 'accepted_score_sum': accepted_score_sum, 'accepted_count': accepted_count}
    }

